from pathlib import Path
import textwrap
R=Path.cwd()
M=[('01-Python','Python','syntax, types, control flow, functions, collections, files, exceptions, OOP, modules, generators, decorators, typing, tests'),('02-SQL','SQL','SELECT, joins, aggregation, subqueries, CTEs, windows, schema design, indexes, transactions'),('03-NumPy-Pandas','NumPy and Pandas','arrays, vectorization, cleaning, missing values, joins, groupby, time series'),('04-Statistics','Statistics','descriptive statistics, probability, distributions, sampling, confidence intervals, hypothesis tests, regression'),('05-Data-Visualization','Visualization','Matplotlib, Seaborn, chart choice, design, storytelling, dashboards'),('06-EDA','Exploratory Data Analysis','data quality, univariate and bivariate analysis, leakage, feature hypotheses'),('07-Machine-Learning','Machine Learning','splits, baselines, preprocessing, regression, classification, clustering, metrics, tuning, pipelines'),('08-Deep-Learning','Deep Learning','tensors, neural networks, backpropagation, optimizers, regularization, CNNs, transfer learning'),('09-NLP-and-Generative-AI','NLP and Generative AI','text, embeddings, transformers, prompting, structured output, tools, RAG, evaluation, safety'),('10-FastAPI','FastAPI','REST, validation, inference endpoints, errors, tests, versioning'),('11-Streamlit-Dashboards','Streamlit','widgets, charts, state, uploads, caching, model demos'),('12-Deployment-and-Docker','Deployment and Docker','environments, Docker, configuration, logging, CI, monitoring'),('13-End-to-End-Projects','End-to-End Projects','problem framing, baselines, pipelines, APIs, dashboards, tests, docs'),('14-Exercises','Exercises','Python, SQL, pandas, statistics, ML, NLP, GenAI, APIs'),('15-Interview-Preparation','Interview Preparation','Python, SQL, statistics, ML, DL, NLP, GenAI, system design')]
def w(p,s): p.parent.mkdir(parents=True,exist_ok=True); p.write_text(textwrap.dedent(s).strip()+'\n',encoding='utf-8')
for f,n,t in M:
 b=R/f
 w(b/'README.md',f'# {n}\n\n## Topics\n{t}\n\n## Workflow\nRead lessons; run and modify examples; solve exercises; test normal, boundary and invalid cases; document assumptions, results and limitations.\n\n## Completion\n- [ ] Explain topics\n- [ ] Run examples\n- [ ] Complete exercises\n- [ ] Add tests\n- [ ] Build a mini-project')
 w(b/'lessons'/'01-roadmap.md',f'# {n}: roadmap\n\nThis module covers {t}.\n\nFor every concept: define it, implement a small example, predict and verify output, test edge cases, compare a baseline with an improved approach, and explain limitations.')
 w(b/'exercises'/'README.md',f'# {n} exercises\n\nCreate solutions with the prompt, code/query, expected and actual output, tests, and explanation. Include fundamentals, a practical scenario, debugging, edge cases, and one extension.')
examples={'01_variables.py':"name='Asha'; age=21; score=87.5; print(name,age,score)",'02_control_flow.py':"score=82; grade='A' if score>=90 else 'B' if score>=75 else 'C'; print(grade)",'03_functions.py':"def mean(xs):\n if not xs: raise ValueError('empty values')\n return sum(xs)/len(xs)\nprint(mean([2,4,6]))",'04_collections.py':"scores={'Asha':90,'Ravi':78,'Mina':85}; print(sorted(scores.items(),key=lambda x:x[1],reverse=True))",'05_files.py':"from pathlib import Path\np=Path('sample_output.txt'); p.write_text('Reliable data matters.\\n',encoding='utf-8'); print(p.read_text(encoding='utf-8').strip())",'06_oop.py':"class Summary:\n def __init__(self,x): self.x=list(x)\n def mean(self): return sum(self.x)/len(self.x)\nprint(Summary([2,4,6]).mean())",'07_comprehensions.py':"print([n*n for n in range(1,6)])",'08_csv.py':"import csv\nfrom pathlib import Path\np=Path('scores.csv')\nwith p.open('w',newline='',encoding='utf-8') as f: csv.writer(f).writerows([['name','score'],['Asha',90]])\nwith p.open(newline='',encoding='utf-8') as f: print(list(csv.reader(f)))"}
for n,c in examples.items(): w(R/'01-Python'/'examples'/n,c)
w(R/'02-SQL'/'lessons'/'02-practice.sql','''CREATE TABLE customers (id INTEGER PRIMARY KEY, name VARCHAR(100));\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, amount DECIMAL(10,2));\nSELECT c.id,c.name,SUM(o.amount) revenue FROM customers c JOIN orders o ON o.customer_id=c.id GROUP BY c.id,c.name ORDER BY revenue DESC;\nSELECT c.id,c.name FROM customers c LEFT JOIN orders o ON o.customer_id=c.id WHERE o.id IS NULL;''')
w(R/'03-NumPy-Pandas'/'examples'/'pandas_cleaning.py',"import pandas as pd\ndf=pd.DataFrame({'name':['Asha','Ravi','Mina','Mina'],'age':[21,None,24,24]})\ndf=df.drop_duplicates().copy(); df['age']=df['age'].fillna(df['age'].median()); print(df)")
w(R/'07-Machine-Learning'/'lessons'/'02-workflow.md','Define target and metric; split before fitting transformations; establish a baseline; use pipelines; tune on training/validation data; reserve test data for final evaluation; inspect errors, leakage, calibration and subgroup performance.')
w(R/'09-NLP-and-Generative-AI'/'lessons'/'02-rag-checklist.md','''# RAG checklist\n\n1. Use documents you are allowed to process. 2. Chunk text and preserve source metadata. 3. Retrieve relevant passages. 4. Answer from evidence and admit when evidence is insufficient. 5. Return real citations, never invented ones. 6. Evaluate retrieval, correctness, groundedness, latency and cost. 7. Treat retrieved text as untrusted; test prompt injection and protect sensitive data.''')
P=[('customer-churn','Customer churn','Clean data, inspect class balance, compare a baseline classifier, report precision/recall, check leakage.'),('sales-dashboard','Sales dashboard','Validate dates and amounts, summarize revenue, plot trends, document caveats.'),('house-prices','House price prediction','Split data, build a pipeline, compare baseline, report MAE/RMSE.'),('document-rag','Document RAG assistant','Chunk permitted documents, retrieve evidence, cite sources, evaluate groundedness.'),('model-api','ML model API','Serve validated predictions and test valid/invalid API requests.')]
for s,n,d in P:w(R/'13-End-to-End-Projects'/s/'README.md',f'# {n}\n\n{d}\n\n- [ ] Problem and metric\n- [ ] Data checks\n- [ ] Baseline and evaluation\n- [ ] Tests and run instructions\n- [ ] Limitations')
w(R/'requirements.txt','numpy\npandas\nmatplotlib\nseaborn\nscikit-learn\nscipy\njupyter\npytest\nfastapi\nuvicorn\nstreamlit')
w(R/'tests'/'test_course_structure.py',"import unittest\nfrom pathlib import Path\nR=Path(__file__).resolve().parents[1]\nclass TestCourse(unittest.TestCase):\n def test_modules(self):\n  fs=[p for p in R.iterdir() if p.is_dir() and p.name[:2].isdigit()]; self.assertGreaterEqual(len(fs),15)\n  for p in fs:\n   with self.subTest(module=p.name): self.assertTrue((p/'README.md').exists())\n def test_examples(self): self.assertGreaterEqual(len(list((R/'01-Python'/'examples').glob('*.py'))),8)\n def test_rag(self): self.assertTrue((R/'09-NLP-and-Generative-AI'/'lessons'/'02-rag-checklist.md').exists())\nif __name__=='__main__': unittest.main(verbosity=2)")
w(R/'README.md','# Full-Stack Data Science + Generative AI\n\nFollow numbered modules in order. Run examples, solve exercises, add tests, and document results. Install dependencies with `python -m pip install -r requirements.txt`. Run checks with `python -m unittest discover -s tests -v`.\n\n## Curriculum\n'+'\n'.join(f'- [{n}]({f}/README.md): {t}.' for f,n,t in M)+'\n\n## Projects\n'+'\n'.join(f'- {n}' for _,n,_ in P)+'\n\nThis is a generated learning scaffold, not a guarantee of mastery or production readiness. Datasets, model weights, credentials, external services and deployment must be configured and verified separately.')
w(R/'COURSE_STATUS.md','Generated course scaffold, roadmaps, examples, practice prompts, project briefs, and structure tests. Mark topics complete only after running code, solving exercises, testing results, and reviewing limitations.')
print(f'Generated {len(M)} modules, {len(P)} project briefs and {len(examples)} Python examples in {R}')
